package com.example.media;

import java.io.IOException;
import java.util.Arrays;
import java.util.List;

public class ThumbnailService {
    public interface CommandRunner {
        int run(List<String> command) throws IOException;
    }

    private final CommandRunner runner;

    public ThumbnailService(CommandRunner runner) {
        this.runner = runner;
    }

    /** Render a 128px thumbnail next to the uploaded image. */
    public int createThumbnail(String uploadName) throws IOException {
        String command = "convert " + uploadName + " -resize 128x128 thumb_" + uploadName;
        return runner.run(Arrays.asList("sh", "-c", command));
    }
}

package com.example.media;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class ThumbnailServiceTest {
    @Test
    void returnsRunnerStatus() throws Exception {
        assertEquals(0, new ThumbnailService(command -> 0).createThumbnail("cat.png"));
    }
}
